<!--vbase-->
<template>
  <div
    v-if="error"
    class="q-dialog fullscreen no-pointer-events q-dialog--modal banner-parent"
  >
    <div
      class="q-dialog__backdrop fixed-full"
      aria-hidden="true"
      style="--q-transition-duration: 300ms"
    ></div>
    <div class="error-banner row q-dialog__inner all-pointer-events">
      <span class="left-side">
        <q-btn class="reload-doc text-weight-bold" to="/dashboard">
          Dashboard
        </q-btn>
      </span>

      <span class="message">
        <span v-if="errors.hasOwnProperty(error_message)">
          {{ $t(errors[error_message]) }}
        </span>
        <span v-else>
          {{ $t(errors['general']) }}
        </span>
        <!-- DOP-70: the id of the request that failed, for the support ticket. -->
        <button
          v-if="traceId"
          type="button"
          class="error-trace-id"
          data-test="document-error-trace-id"
          :title="$t('login_error_trace_id_copy')"
          @click="copyTraceId"
        >
          {{ $t('login_error_trace_id') }}: <span class="font-mono">{{ traceId }}</span>
        </button>
      </span>

      <span class="right-side"> </span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocumentStore } from 'src/store/main';
import { dynamicObj } from '../assets';
import { recentFailedTraceId } from 'src/utils/errorTraceId';

export default defineComponent({
  el: '#app',
  mixins: [],
  components: {},
  data() {
    return {
      errors: {
        invalid: 'INVALID_DOCUMENT',
        permission: 'doc_permission_error',
        general: 'error_internal_occur',
        invalid_status: 'doc_invalid_status_error',
        error_status: 'document_has_error_status',
        record_not_found: 'record_not_found',
      } as dynamicObj,
      traceId: '',
    };
  },
  watch: {
    error: {
      immediate: true,
      handler(value: boolean) {
        // The document request that failed a moment ago is what put the banner up.
        this.traceId = value ? recentFailedTraceId() : '';
      },
    },
  },
  methods: {
    copyTraceId() {
      navigator.clipboard?.writeText(this.traceId).catch(() => {
        // No clipboard (insecure context): the id stays visible and selectable.
      });
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { error, error_message } = storeToRefs(doc_store);
    return {
      error,
      error_message,
    };
  },
});
</script>

